"""Test 16: the side-by-side table of section 5 and the tables of the report, from fits-t16.json (read_t16.py) and
scorecard-t16.json (Sandhi version 4's scorer, as it wrote it). Any difference between the scorer's computed duties, sharing
ratios and tau_c and this read's is listed, not reconciled. The table is added to fits-t16.json under
"section_5_side_by_side"; nothing else in fits-t16.json is changed. The scorecard is read and not changed.

Usage: python -I -B tables_t16.py"""
from __future__ import annotations

import sys

sys.dont_write_bytecode = True

import json  # noqa: E402
from pathlib import Path  # noqa: E402

HERE = Path(__file__).resolve().parent
FIELDS = ["ratio", "threshold", "duty_b", "lag_1_over_e", "tau_c_s", "telegraph_sd", "mid_sweep_fraction_middle_fifth"]
KEYMAP = {"day3-job2": "d3-job2", "day3-job3": "d3-job3", "day3-job1": "d3-job1"}


def qrec_of(s):
    q = s["quadrature_of_record"]
    return q.get("monitor") if isinstance(q, dict) else q   # the scorer stores it per wait, as {"monitor": "Y"}


def f(x, n=4):
    if x is None:
        return "none"
    if isinstance(x, bool):
        return "yes" if x else "no"
    if isinstance(x, int):
        return str(x)
    return f"{x:.{n}f}"


def main():
    fits = json.loads((HERE / "fits-t16.json").read_text())
    card = json.loads((HERE / "scorecard-t16.json").read_text())
    rows, diffs = [], []
    for job in card["jobs"]:
        mine = fits["jobs"][KEYMAP[job["key"]]]["qubits"]["143"]["waits"]["monitor"]
        fit_spans = {s["id"]: s for s in (job.get("fit") or {}).get("spans", [])}
        for s in job["series"]:
            ms = next(x for x in mine["spans"] if x["span"] == s["span"])
            for ci, c in enumerate(s["circuits"]):
                q = c["quadrature"]
                sc = s["readings"][ci]
                for fld in FIELDS:
                    a, b = sc.get(fld), ms[q].get(fld)
                    d = (a - b) if (a is not None and b is not None) else None
                    eq = (abs(d) <= 1e-12) if d is not None else (a is b)
                    rows.append({"job": job["key"], "span": s["span"], "quadrature": q, "field": fld, "scorer": a, "this_read": b, "difference": d, "equal": eq})
                    if not eq:
                        diffs.append(rows[-1])
            fs = fit_spans.get(s["id"], {})
            rows.append({"job": job["key"], "span": s["span"], "quadrature": qrec_of(s), "field": "model_duty (the scorer's own fit, beside)",
                         "scorer": fs.get("b"), "this_read": None, "difference": None, "equal": None})
            rows.append({"job": job["key"], "span": s["span"], "quadrature": qrec_of(s), "field": "model_ell_seconds (the scorer's own fit, beside)",
                         "scorer": (fs["ell"] * s["sweep_s"]) if fs.get("ell") is not None else None, "this_read": None, "difference": None, "equal": None})
            # the scorer's span membership and repeats against this read's
            for fld, a, b in (("whole_repeats", len(s["whole_repeats"]) if isinstance(s.get("whole_repeats"), list) else s.get("whole_repeats"), ms["n_whole_repeats"]),
                              ("quadrature_of_record", s["quadrature_of_record"].get("monitor") if isinstance(s["quadrature_of_record"], dict) else s["quadrature_of_record"],
                               mine["quadrature_of_record"]),   # the scorer stores it per wait, as {"monitor": "Y"}
                              ("duration_s", s["duration_s"], ms[mine["quadrature_of_record"]]["duration_s"])):
                eq = a == b
                rows.append({"job": job["key"], "span": s["span"], "quadrature": None, "field": fld, "scorer": a, "this_read": b, "difference": None, "equal": eq})
                if not eq:
                    diffs.append(rows[-1])
    brow = []
    mineb = {(b["job"], tuple(b["spans"])): b for b in fits["boundaries"]}
    for b in card["boundaries"]:
        m = mineb[(KEYMAP[b["job"]], tuple(b["spans"]))]
        t = b["test15"]
        eq = abs(t["ratio"] - m["ratio"]) <= 1e-12 and t["word"] == m["word"]
        brow.append({"job": b["job"], "spans": b["spans"], "scorer_ratio": t["ratio"], "this_read_ratio": m["ratio"], "scorer_word": t["word"], "this_read_word": m["word"], "equal": eq,
                     "scorer_LR": b.get("likelihood_ratio", {}).get("LR"), "scorer_LR_p_bootstrap": b.get("likelihood_ratio", {}).get("p_bootstrap")})
        if not eq:
            diffs.append(brow[-1])
    bj = card["between_jobs"][0]
    mbj = fits["between_jobs"]["rows"][0]
    eqj = abs(bj["ratio"] - mbj["ratio"]) <= 1e-12 and bj["word"] == mbj["word"]
    between = {"scorer_ratio": bj["ratio"], "this_read_ratio": mbj["ratio"], "scorer_word": bj["word"], "this_read_word": mbj["word"], "equal": eqj,
               "scorer_LR": bj.get("likelihood_ratio", {}).get("LR"), "scorer_LR_p_bootstrap": bj.get("likelihood_ratio", {}).get("p_bootstrap")}
    if not eqj:
        diffs.append(between)
    shuf = []
    j1 = fits["job1"]
    for s in card["shuffled"][0]["spans"]:
        ms = next(x for x in j1["spans"] if x["span"] == s["span"])
        for q in ("Y", "X"):
            r = s["quadratures"][q]["reading"]
            for fld in ("ratio", "row_lag1_autocorrelation_mean", "n_rows"):
                a, b = r.get(fld), ms[q].get(fld)
                eq = a == b if isinstance(a, int) else (a is not None and b is not None and abs(a - b) <= 1e-12)
                shuf.append({"span": s["span"], "quadrature": q, "field": fld, "scorer": a, "this_read": b, "equal": eq})
                if not eq:
                    diffs.append(shuf[-1])
    fits["section_5_side_by_side"] = {"note": "the scorer's own test 15 readings (record_io.record_reading, per span and circuit) beside this read's (read_t15.readings); any difference listed, not reconciled",
                                      "span_rows": rows, "boundaries": brow, "between_jobs": between, "shuffled_job1": shuf,
                                      "differences": diffs, "n_compared": len([r for r in rows if r["equal"] is not None]) + len(brow) + 1 + len(shuf)}
    (HERE / "fits-t16.json").write_text(json.dumps(fits))

    # ---------------------------------------------------------------- the tables of the report
    L = ["# Test 16: tables", "", "Generated by `tables_t16.py` from `fits-t16.json` and `scorecard-t16.json`.", ""]
    L += ["## The monitors per span (quadrature of record Y; X beside)", "",
          "| job | span | whole repeats | ratio Y | word | ratio X | duty b | b at 20 to 80 | 1/e lag | τ_c (s) | telegraph sd | switches | dwell high, low (s) | quarter-span duties | mid fifth | 0.2 to 0.8 | lag 1 per row Y |",
          "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for key in ("d3-job2", "d3-job3"):
        wd = fits["jobs"][key]["qubits"]["143"]["waits"]["monitor"]
        for s in wd["spans"]:
            y, x = s["Y"], s["X"]
            L.append(f"| {key} | {s['span']} | {s['n_whole_repeats']} | {f(y['ratio'], 2)} | {y['word']} | {f(x['ratio'], 2)} | {f(y['duty_b'], 3)} | {f(y['duty_b_at_threshold_20_80'], 3)} | {y['lag_1_over_e']} | {f(y['tau_c_s'], 3)} | {f(y['telegraph_sd'], 4)} | {y['switches']} | {f(y['dwell_high_s'], 3)}, {f(y['dwell_low_s'], 3)} | {', '.join(f(v, 3) for v in y['quarter_span_duties'])} | {f(y['mid_sweep_fraction_middle_fifth'], 3)} | {f(y['fraction_between_0p2_and_0p8'], 3)} | {f(y['row_lag1_autocorrelation_mean'], 3)} |")
    L += ["", "## The X quadrature per span, beside", "", "| job | span | ratio | duty b | 1/e lag | τ_c (s) | telegraph sd | switches | mid fifth | lag 1 per row |", "|---|---|---|---|---|---|---|---|---|---|"]
    for key in ("d3-job2", "d3-job3"):
        wd = fits["jobs"][key]["qubits"]["143"]["waits"]["monitor"]
        for s in wd["spans"]:
            x = s["X"]
            L.append(f"| {key} | {s['span']} | {f(x['ratio'], 2)} | {f(x['duty_b'], 3)} | {x['lag_1_over_e']} | {f(x['tau_c_s'], 3)} | {f(x['telegraph_sd'], 4)} | {x['switches']} | {f(x['mid_sweep_fraction_middle_fifth'], 3)} | {f(x['row_lag1_autocorrelation_mean'], 3)} |")
    L += ["", "## The autocorrelation of the sweep means at lags 490 to 510 (Y), beside, no word", "", "| job | span | at 490 | at 500 | at 510 | smallest | largest |", "|---|---|---|---|---|---|---|"]
    for key in ("d3-job2", "d3-job3"):
        wd = fits["jobs"][key]["qubits"]["143"]["waits"]["monitor"]
        for s in wd["spans"]:
            a = s["Y"]["acf_lags_490_to_510"]
            L.append(f"| {key} | {s['span']} | {f(a[0], 3)} | {f(a[10], 3)} | {f(a[20], 3)} | {f(min(a), 3)} | {f(max(a), 3)} |")
    L += ["", "## Section 5: the scorer's readings beside this read's", "",
          f"Compared: {fits['section_5_side_by_side']['n_compared']} quantities. Differences: {len(diffs)}.", "",
          "| job | span | quadrature | field | scorer | this read | equal |", "|---|---|---|---|---|---|---|"]
    for r in rows:
        if r["field"] in ("ratio", "duty_b", "tau_c_s", "telegraph_sd") or r["field"].startswith("model_"):
            L.append(f"| {r['job']} | {r['span']} | {r['quadrature']} | {r['field']} | {f(r['scorer'], 6) if isinstance(r['scorer'], float) else r['scorer']} | {f(r['this_read'], 6) if isinstance(r['this_read'], float) else (r['this_read'] if r['this_read'] is not None else '')} | {'' if r['equal'] is None else ('yes' if r['equal'] else 'NO')} |")
    (HERE / "tables-t16.md").write_text("\n".join(L) + "\n")
    print(json.dumps({"n_compared": fits["section_5_side_by_side"]["n_compared"], "differences": diffs}, indent=1, default=str))


if __name__ == "__main__":
    main()
